import { Address } from '../address.js';
import { Bps } from '../bps.js';
import { FeeTakerExt } from '../limit-order/index.js';
export function buildIntegratorFeeFromFeeInfo(feeParams) {
    var integratorFeeBps = feeParams.integratorFeeBps, integratorFeeReceiver = feeParams.integratorFeeReceiver, integratorFeeSharePercent = feeParams.integratorFeeSharePercent;
    if (integratorFeeBps === undefined || integratorFeeBps <= 0 || !integratorFeeReceiver || integratorFeeSharePercent === undefined) {
        return FeeTakerExt.IntegratorFee.ZERO;
    }
    return new FeeTakerExt.IntegratorFee(new Address(integratorFeeReceiver), new Address(feeParams.protocolFeeReceiver), new Bps(BigInt(integratorFeeBps)), Bps.fromSharePercent(integratorFeeSharePercent));
}
